import { GRSettings } from '../../../slots/core/model/GRSettings';
import { ICascadeSettings } from '../types';

const DEFAULT_CASCADE_SETTINGS: ICascadeSettings = ({
    cascadeFallSettings: {
        fallTime: 0.5,
        fallOffset: 0,
    },
    cascadeBounceSettings: {
        duration: 0.1,
        offset: 20,
    },
    cascadeRemoveDelay: 0.15,
    cascadeBlockFallDelay: 0,
    cascadeTease: {
        newSymbolsDelay: 0,
        reelStaggerDelay: 0,
    }
});

export class GCSettings extends GRSettings {

    private _cascadeSettings: ICascadeSettings;

    constructor() {
        super();
        this._cascadeSettings = DEFAULT_CASCADE_SETTINGS;
    }

    public updateCascadeSettings(settings: ICascadeSettings | Partial<ICascadeSettings>): void {
        this._cascadeSettings = { ...this._cascadeSettings, ...settings };
    }

    public get cascadeSettings(): ICascadeSettings {
        return this._cascadeSettings;
    }
}